  spindle_rpm_above_max: ["Tool {tool}: {value} rpm, the spindle gives up to {limit} (the job is sent with {limit})", "Herramienta {tool}: {value} rpm, el husillo da hasta {limit} (el trabajo se envía con {limit})", "Utensile {tool}: {value} giri/min, il mandrino arriva a {limit} (il lavoro viene inviato con {limit})", "Werkzeug {tool}: {value} U/min, die Spindel gibt bis {limit} (der Auftrag geht mit {limit} hinaus)", "Outil {tool} : {value} tr/min, la broche donne jusqu'à {limit} (le travail est envoyé avec {limit})", "Ferramenta {tool}: {value} rpm, o fuso dá até {limit} (o trabalho é enviado com {limit})", "刀具 {tool}：{value} rpm，主轴最高 {limit}（作业按 {limit} 发送）", "工具 {tool}：{value} rpm、スピンドルは最大 {limit}（ジョブは {limit} で送信されます）"],
